function buildWishSuggestion(wish){const requester=state.players.find(p=>p.name===wish.playerName&&p.status==='waiting'&&isAvailableNow(p));if(!requester)return null;const waiting=state.players.filter(p=>p.status==='waiting'&&isAvailableNow(p)&&p.id!==requester.id).sort((a,b)=>Math.abs(a.rating-requester.rating)-Math.abs(b.rating-requester.rating));if(wish.type==='partner'){const target=waiting.find(p=>p.name.toLowerCase()===wish.target.toLowerCase()&&!pairIsBlocked(requester,p));if(!target)return null;const others=waiting.filter(p=>p.id!==target.id).slice(0,2);return others.length===2?[requester,target,...others]:null}if(wish.type==='opponent'){const target=waiting.find(p=>p.name.toLowerCase()===wish.target.toLowerCase());if(!target)return null;const others=waiting.filter(p=>p.id!==target.id).slice(0,2);return others.length===2?[requester,others[0],target,others[1]]:null}if(wish.type==='mixed'){const mate=waiting.find(p=>p.gender!==requester.gender&&!pairIsBlocked(requester,p));if(!mate)return null;const left=waiting.filter(p=>p.id!==mate.id),male=left.find(p=>p.gender==='男'),female=left.find(p=>p.gender==='女'&&p.id!==male?.id);if(!male||!female||pairIsBlocked(male,female))return null;return[requester,mate,male,female]}if(wish.type==='boss'){const mate=waiting[0],bosses=shuffle(state.bossPlayers.filter(p=>p.status==='boss'&&isAvailableNow(p))).slice(0,2);return mate&&bosses.length===2?[requester,mate,...bosses]:null}return null}
