function showCourt(id){const c=state.courts.find(c=>c.id===id),ps=c.players.map(player);openModal(`<p class="eyebrow">COURT ${id}</p><h2>場上球友</h2><p class="sub">比賽已進行 ${Math.floor((Date.now()-c.start)/60000)} 分鐘</p>${ps.map((p,i)=>`<div class="leader-row"><span>${i<2?'A':'B'}</span><strong>${p.name}</strong><strong>${p.rating} 分</strong></div>`).join('')}<div class="modal-actions"><button class="secondary" data-close>關閉</button><button class="primary" onclick="closeModal();finishCourt(${id})">結束比賽</button></div>`)}
