function setBinding(p,mateId,session){detachBinding(p);if(!mateId)return;const mate=state.players.find(x=>x.id===mateId);if(!mate)return;detachBinding(mate);p.boundPartnerId=mate.id;mate.boundPartnerId=p.id;p.boundSession=session;mate.boundSession=session}
function savePlayer(id){const p=player(id),signupLevel=+$('#edit-signup-level').value,from=$('#edit-available-from').value,until=$('#edit-available-until').value,preferred=$$('[data-partner-kind="preferred"]:checked').map(x=>+x.value),blocked=$$('[data-partner-kind="blocked"]:checked').map(x=>+x.value),boundId=+$('#edit-bound-partner').value||null,boundSession=$('#edit-bound-session').value,mate=boundId?state.players.find(x=>x.id===boundId):null;if(!signupLevel||signupLevel<1||signupLevel>15)return toast('報名等級請輸入 1–15');if(!from||!until||timeToMinutes(from)>=timeToMinutes(until))return toast('可上場開始時間必須早於離場時間');if(preferred.some(id=>blocked.includes(id)))return toast('同一球友不能同時設為偏好與拒絕搭檔');if(boundId&&(blocked.includes(boundId)||(mate?.blockedPartnerIds||[]).includes(p.id)))return toast('綁定球友不能同時設為拒絕搭檔');p.gender=$('#edit-gender').value;p.wishPoints=Math.max(0,+$('#edit-wish-points').value||0);p.voiceAliases=$('#edit-voice-aliases').value.split(/[,，、\n]+/).map(x=>x.trim()).filter(Boolean);p.signupLevel=signupLevel;p.rating=+$('#edit-rating').value;p.level=$('#edit-level').value;p.games=+$('#edit-games').value;p.availableFrom=from;p.availableUntil=until;p.targetGames=Math.max(1,+$('#edit-target-games').value||1);p.preferredPartnerIds=preferred;p.blockedPartnerIds=blocked;p.partner=preferenceNames(preferred)[0]||'—';setBinding(p,boundId,boundSession);if(p.status!=='playing')p.status=$('#edit-status').value;state.suggestion=[];state.simulation=null;closeModal();render();toast(boundId?`${p.name} 已與 ${mate.name} 綁定 ${boundSession} 時段出場`:'球友資料已更新')}
function syncInitialRating(){const level=+$('#new-signup-level').value||0;$('#new-rating').value=Math.round(level*100);$('#initial-rating-preview').textContent=`Lv.${level} × 100 = ${Math.round(level*100)} 分 · 初始許願點 3 點`}
let addNewMemberToSession=false;
function addPerson(toCurrentSession=false){addNewMemberToSession=Boolean(toCurrentSession);openModal(`<p class="eyebrow">NEW PLAYER</p><h2>${addNewMemberToSession?'建立並加入本場':'新增永久成員'}</h2><p class="sub">輸入性別與報名等級後，初始動態積分為等級 × 100。</p><div class="form-grid"><label class="full">暱稱<input id="new-name" placeholder="例如：小羽"></label><label>性別<select id="new-gender"><option value="男">男</option><option value="女">女</option></select></label><label>報名等級<input id="new-signup-level" type="number" min="1" max="15" step="0.5" value="7" oninput="syncInitialRating()"></label><label>初始動態積分<input id="new-rating" type="number" value="700" readonly></label><label>程度標籤<select id="new-level"><option>中階</option><option>進階</option><option>初階</option></select></label>${addNewMemberToSession?'<label>參加時段<select id="new-session"><option value="B">B · 18:00–20:30</option><option value="C">C · 20:30–22:30</option><option value="B+C">B+C · 全時段</option></select></label>':''}<label>目標場數<input id="new-target-games" type="number" min="1" max="20" value="5"></label><label>可上場時間<input id="new-available-from" type="time" value="18:00"></label><label>最晚離場時間<input id="new-available-until" type="time" value="20:30"></label><p id="initial-rating-preview" class="sub full">Lv.7 × 100 = 700 分 · 初始許願點 3 點</p></div><div class="modal-actions"><button class="secondary" data-close>取消</button><button class="primary" onclick="confirmAdd()">${addNewMemberToSession?'建立並加入本場':'建立永久成員'}</button></div>`)}
function confirmAdd(){const name=$('#new-name').value.trim(),signupLevel=+$('#new-signup-level').value,from=$('#new-available-from').value,until=$('#new-available-until').value;if(!name)return toast('請輸入暱稱');if(state.players.some(p=>normalizeMemberKey(p.name)===normalizeMemberKey(name)))return toast('已有同名成員，請從既有成員加入本場');if(!signupLevel||signupLevel<1||signupLevel>15)return toast('報名等級請輸入 1–15');if(timeToMinutes(from)>=timeToMinutes(until))return toast('可上場開始時間必須早於離場時間');const rating=Math.round(signupLevel*100),session=addNewMemberToSession?$('#new-session').value:'';const p={id:Math.max(0,...state.players.map(p=>Number(p.id)||0))+1,name,session,gender:$('#new-gender').value,signupLevel,rating,level:$('#new-level').value,games:0,wait:0,status:addNewMemberToSession?'waiting':'absent',paid:false,wins:0,losses:0,winStreak:0,wishPoints:3,ratingGainBank:0,attendance:100,partner:'—',voiceAliases:[],preferredPartnerIds:[],blockedPartnerIds:[],boundPartnerId:null,boundSession:'B+C',availableFrom:from,availableUntil:until,targetGames:Math.max(1,+$('#new-target-games').value||1)};state.players.push(p);if(addNewMemberToSession)state.rosterIds.push(p.id);state.suggestion=[];state.simulation=null;closeModal();render();toast(addNewMemberToSession?`${name} 已加入 ${session} 時段`:`${name} 已建立為永久成員`)}

$$('[data-close]').forEach(x=>x.addEventListener('click',closeModal));$('#modal').addEventListener('click',e=>{if(e.target.matches('[data-close]'))closeModal()});
function activateView(view){const b=$(`.nav-item[data-view="${view}"]`);if(!b)return;$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.view').forEach(x=>x.classList.remove('active'));$(`#${view}-view`).classList.add('active');const titles={courts:'今晚，一起打場好球',create:'建立新的排點場次',members:'讓每位球友都有位置',history:'每場對戰都值得記住',simulation:'用數據驗證每一次排點',settings:'排出公平，也排出樂趣'};$('#page-title').textContent=titles[view];if(view==='create')setCreateMethod('line');history.replaceState(null,'',`?view=${view}`)}
$('#nav').addEventListener('click',e=>{const b=e.target.closest('.nav-item');if(b)activateView(b.dataset.view)});
$('#sidebar-toggle').onclick=toggleSidebar;
$('#open-live-board').onclick=showLiveBoard;
$('#pool-tabs').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;$$('#pool-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.pool=b.dataset.pool;renderPool()});
$('#auto-mode').onclick=()=>setArrangementMode('auto');$('#manual-mode').onclick=()=>setArrangementMode('manual');
$('#voice-listen').onclick=startVoiceCommand;$('#voice-command-form').onsubmit=event=>{event.preventDefault();applyVoiceCommand()};
$('#match-type-mode').value=state.matchTypeMode;$('#match-type-mode').onchange=event=>{state.matchTypeMode=event.target.value;state.suggestion=[];state.funMode='';getSuggestion();renderSuggestion();renderPool();renderFunStatus();saveState();toast(`已切換為 ${event.target.selectedOptions[0].textContent}`)};
$$('[data-fun]').forEach(button=>button.onclick=()=>generateFunMatch(button.dataset.fun));
$('#refresh-match').onclick=()=>{state.funMode='';const result=getSuggestion(true);renderSuggestion();renderPool();renderFunStatus();saveState();if(!result.candidateCount)toast('目前沒有符合條件的四人組合');else if(!result.changed)toast('目前限制下只有這一種合格組合');else toast(`已切換至第 ${result.rank}/${result.candidateCount} 個均衡方案`)};
$('#assign-match').onclick=()=>{const c=activeCourts().find(c=>c.status==='idle');c?assignToCourt(c.id):toast(`${activeSession().label}目前沒有空場`)};$('#auto-arrange').onclick=$('#assign-match').onclick;
$('#add-player').onclick=showAddSessionPlayer;$('#add-member').onclick=()=>addPerson(false);$('#create-import-line').onclick=showLineNoteImport;$('#create-method-line').onclick=()=>setCreateMethod('line');$('#create-method-manual').onclick=()=>setCreateMethod('manual');$('#manual-member-search').oninput=renderManualRoster;$('#create-manual-session').onclick=createManualSession;$('#member-search').oninput=renderMembers;$('#level-filter').onchange=renderMembers;
$('#payment-reminder-toggle').onclick=togglePaymentReminder;
$('#court-session-switch').onchange=event=>switchCourtSession(event.target.value);
$('#sound-toggle').onclick=()=>{state.sound=!state.sound;$('#sound-toggle').textContent=state.sound?'♬':'♩';toast(state.sound?'語音播報已開啟':'語音播報已靜音')};
$('#connectivity-status').onclick=showOfflineGuide;
$('#fullscreen').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();
$$('[data-step]').forEach(b=>b.onclick=()=>{state.gameLimit=Math.max(1,state.gameLimit+ +b.dataset.delta);$('#limit-setting').textContent=state.gameLimit});
$('#save-settings').onclick=()=>toast('排點設定已儲存');$('#edit-suggestion').onclick=()=>setArrangementMode(state.arrangementMode==='manual'?'auto':'manual');
$('#export-history').onclick=()=>{const rows=['場地,A隊,B隊,比分,時間',...state.history.map(h=>`${h.court},${h.a.join('/')},${h.b.join('/')},${h.score},${h.time}`)];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+rows.join('\n')],{type:'text/csv'}));a.download='羽球對戰紀錄.csv';a.click();URL.revokeObjectURL(a.href)};
$('#run-simulation').onclick=runSimulation;$('#export-simulation').onclick=()=>{if(!state.simulation)return toast('請先執行模擬測試');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state.simulation,null,2)],{type:'application/json'}));a.download='排點模擬測試報告.json';a.click();URL.revokeObjectURL(a.href)};
$('#simulation-session').onchange=event=>setSimulationSession(event.target.value);
window.addEventListener('resize',()=>fitVisibleNames());
function bootConsole(){registerOfflineApp();setInterval(renderElapsed,1000);setInterval(()=>{rosterPlayers().filter(p=>p.status==='waiting'&&isAvailableNow(p)).forEach(p=>p.wait++);renderCourts();renderSuggestion();renderPool();saveState();publishLiveState()},60000);setInterval(refreshWishes,5000);renderElapsed();render();refreshWishes();if(!state.simulation||state.simulation.session!==state.simulationSessionKey)runSimulation();activateView(new URLSearchParams(location.search).get('view')||'courts')}
bootConsole();
